import verifiers as vf
from verifiers.utils.data_utils import extract_boxed_answer
from datasets import Dataset
from huggingface_hub import hf_hub_download
import json
import os
import zipfile

def load_environment(
    num_train_examples: int = -1,
    num_eval_examples: int = -1,
    use_few_shot: bool = False,
):
    """
    Single-turn Legal Natural Language Inference (NLI) environment using the
    `kiddothe2b/contract-nli` dataset from Hugging Face.

    - Formats each example as a chat message requiring Chain-of-Thought reasoning
      inside <think>...</think> and a final answer inside
      \boxed{ENTAILMENT|NEUTRAL|CONTRADICTION}.
    - Rewards an exact match on the final label parsed from the \boxed{...} block.
    """
    # Load dataset without using deprecated dataset scripts.
    # We download the JSONL archive and construct splits locally.
    repo_id = "kiddothe2b/contract-nli"
    zip_filename = "contract_nli.zip"
    jsonl_name = "contract_nli_v1.jsonl"

    zip_path = hf_hub_download(repo_id=repo_id, repo_type="dataset", filename=zip_filename)
    extract_dir = os.path.join(os.path.dirname(zip_path), "contract_nli_extracted")
    os.makedirs(extract_dir, exist_ok=True)
    jsonl_path = os.path.join(extract_dir, jsonl_name)
    if not os.path.exists(jsonl_path):
        with zipfile.ZipFile(zip_path) as zf:
            with zf.open(jsonl_name) as f_in, open(jsonl_path, "w", encoding="utf-8") as f_out:
                for line in f_in:
                    f_out.write(line.decode("utf-8"))

    # Read JSONL and split by the "subset" field ("train"/"test")
    train_rows: list[dict] = []
    test_rows: list[dict] = []
    with open(jsonl_path, "r", encoding="utf-8") as f:
        for raw in f:
            if not raw.strip():
                continue
            obj = json.loads(raw)
            subset = str(obj.get("subset", "")).strip().lower()
            if subset == "train":
                train_rows.append(obj)
            elif subset == "test":
                test_rows.append(obj)

    dataset = Dataset.from_list(train_rows)
    eval_dataset = Dataset.from_list(test_rows)

    # Allow for subset slicing for quick testing
    if num_train_examples != -1:
        dataset = dataset.select(range(min(num_train_examples, len(dataset))))
    if num_eval_examples != -1:
        eval_dataset = eval_dataset.select(range(min(num_eval_examples, len(eval_dataset))))

    system_prompt = """
    You are a meticulous legal analyst. Your task is to determine the logical relationship between a contract clause (premise) and a hypothesis. Think step-by-step inside <think>...</think>, analyzing the premise and hypothesis carefully for entailment, contradiction, or neutrality.

    Then, output your final conclusion inside \\boxed{...} using EXACTLY ONE of: ENTAILMENT, NEUTRAL, CONTRADICTION.
    Do not include any other text inside the box. Do not include explanations after the box.
    """

    few_shot_examples = []
    if use_few_shot:
        few_shot_examples = [
            {
                "role": "user",
                "content": (
                    "Contract Clause (Premise): \"The Recipient shall not disclose any Confidential Information to third parties without prior written consent.\"\n\n"
                    "Hypothesis: \"Receiving Party will not share Confidential Information with outsiders without permission.\"\n\n"
                    "Based on the premise, is the hypothesis an entailment, neutral, or a contradiction?\n\n"
                    "Answer with one of ENTAILMENT, NEUTRAL, or CONTRADICTION inside \\boxed{...}."
                ),
            },
            {"role": "assistant", "content": "\\boxed{ENTAILMENT}"},
            {
                "role": "user",
                "content": (
                    "Contract Clause (Premise): \"This Agreement does not grant any license or rights to the Confidential Information.\"\n\n"
                    "Hypothesis: \"The Agreement provides a right to use Confidential Information.\"\n\n"
                    "Based on the premise, is the hypothesis an entailment, neutral, or a contradiction?\n\n"
                    "Answer with one of ENTAILMENT, NEUTRAL, or CONTRADICTION inside \\boxed{...}."
                ),
            },
            {"role": "assistant", "content": "\\boxed{CONTRADICTION}"},
            {
                "role": "user",
                "content": (
                    "Contract Clause (Premise): \"The Recipient may use Confidential Information solely to evaluate a potential business relationship.\"\n\n"
                    "Hypothesis: \"The Recipient can disclose the Confidential Information in press releases.\"\n\n"
                    "Based on the premise, is the hypothesis an entailment, neutral, or a contradiction?\n\n"
                    "Answer with one of ENTAILMENT, NEUTRAL, or CONTRADICTION inside \\boxed{...}."
                ),
            },
            {"role": "assistant", "content": "\\boxed{CONTRADICTION}"},
        ]

    def _format_example(example):
        premise = example.get("premise", "")
        hypothesis = example.get("hypothesis", "")

        # Normalize dataset label (supports strings like 'entailment'/'neutral'/'contradiction'
        # and integers 0/1/2 if present)
        raw_label = example.get("label")
        answer_label = "NEUTRAL"
        if isinstance(raw_label, int):
            label_map_int = {0: "ENTAILMENT", 1: "NEUTRAL", 2: "CONTRADICTION"}
            answer_label = label_map_int.get(raw_label, "NEUTRAL")
        elif isinstance(raw_label, str):
            u = raw_label.strip().upper()
            if u in {"ENTAILMENT", "NEUTRAL", "CONTRADICTION"}:
                answer_label = u
            else:
                # handle common lowercase labels
                low = raw_label.strip().lower()
                if low == "entailment":
                    answer_label = "ENTAILMENT"
                elif low == "neutral":
                    answer_label = "NEUTRAL"
                elif low == "contradiction":
                    answer_label = "CONTRADICTION"

        prompt_text = f"Contract Clause (Premise): \"{premise}\"\n\nHypothesis: \"{hypothesis}\"\n\nBased on the premise, is the hypothesis an entailment, neutral, or a contradiction?"
        user_content = f"{prompt_text}\n\nAnswer with one of ENTAILMENT, NEUTRAL, or CONTRADICTION inside \\boxed{{...}}."

        messages = [{"role": "system", "content": system_prompt.strip()}]
        if use_few_shot and few_shot_examples:
            messages.extend(few_shot_examples)
        messages.append({"role": "user", "content": user_content})

        example["prompt"] = messages
        example["premise"] = premise
        example["hypothesis"] = hypothesis
        example["answer"] = answer_label
        return example

    dataset = dataset.map(_format_example)
    eval_dataset = eval_dataset.map(_format_example)

    # Filter to valid examples (ensure we have premise, hypothesis, and valid label)
    def _keep_example(example):
        premise = example.get("premise", "").strip()
        hypothesis = example.get("hypothesis", "").strip()
        answer = example.get("answer", "").strip().upper()

        if not premise or not hypothesis:
            return False
        if answer not in {"ENTAILMENT", "NEUTRAL", "CONTRADICTION"}:
            return False
        return True

    dataset = dataset.filter(_keep_example)
    eval_dataset = eval_dataset.filter(_keep_example)

    parser = vf.ThinkParser(extract_fn=extract_boxed_answer)

    def _completion_to_text(completion):
        if isinstance(completion, str):
            return completion
        if isinstance(completion, list):
            if completion and isinstance(completion[0], dict):
                for msg in reversed(completion):
                    content = msg.get("content")
                    if content:
                        if isinstance(content, list):
                            try:
                                content = " ".join(
                                    (
                                        part.get("text", "") if isinstance(part, dict) else str(part)
                                    )
                                    for part in content
                                )
                            except Exception:
                                content = str(content)
                        return str(content)
                return str(completion[-1])
            return "\n".join(str(x) for x in completion)
        if isinstance(completion, dict):
            content = completion.get("content") or completion.get("text")
            if isinstance(content, list):
                try:
                    content = " ".join(
                        part.get("text", "") if isinstance(part, dict) else str(part)
                        for part in content
                    )
                except Exception:
                    content = str(content)
            if content is not None:
                return str(content)
        return str(completion)

    def correct_label_reward_func(completion, answer=None, **kwargs):
        completion_text = _completion_to_text(completion)
        parsed = (parser.parse_answer(completion_text) or "").strip().upper()

        # Normalize parsed answer - handle common variants
        if parsed not in {"ENTAILMENT", "NEUTRAL", "CONTRADICTION"}:
            if "ENTAIL" in parsed:
                parsed = "ENTAILMENT"
            elif "CONTRADICT" in parsed:
                parsed = "CONTRADICTION"
            elif "NEUTRAL" in parsed:
                parsed = "NEUTRAL"

        # Expected answer
        expected_answer = (answer or "").strip().upper()
        if expected_answer not in {"ENTAILMENT", "NEUTRAL", "CONTRADICTION"}:
            return 0.0

        return 1.0 if parsed == expected_answer else 0.0

    rubric = vf.Rubric(
        funcs=[
            correct_label_reward_func,
            parser.get_format_reward_func(),
        ],
        weights=[1.0, 0.0],
    )

    default_sampling = {"temperature": 0.0, "top_p": 1.0, "max_tokens": 8}

    vf_env = vf.SingleTurnEnv(
        dataset=dataset,
        eval_dataset=eval_dataset,
        system_prompt=system_prompt,
        few_shot=few_shot_examples if use_few_shot else None,
        parser=parser,
        rubric=rubric,
        sampling_args=default_sampling,
    )
    return vf_env

